/* eslint-disable @typescript-eslint/member-ordering */
import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseFilterModel, ICourseFilterModel } from '../../../../data/model/course/CourseFilterModel';
import { CourseService } from '../../../../data/service/course/course.service';
import { CourseFilterComponent } from '../../../components/modal/filter/course-filter/course-filter.component';
import { IonContent, IonRouterOutlet, LoadingController, MenuController, ModalController, ToastController } from '@ionic/angular';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { G } from '../../../../core/common/G';
import { GAccount } from '../../../../core/common/GAccount';
import { SafeUrl } from '@angular/platform-browser';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';
import { Subscription } from 'rxjs';

export interface IQuickTopic {
  title: string;
  query: string;
  icon?: string;
}

export interface ISortOption {
  id: number;
  label: string;
  icon: string;
}

@Component({
  selector: 'app-search',
  templateUrl: './search.component.html',
  styleUrls: ['./search.component.scss']
})
export class SearchComponent implements OnInit, OnDestroy {

  @ViewChild(IonContent) content: IonContent;

  filteredCourses: ICourseFilterModel;
  queryText = '';
  notfound = false;
  isLoading = false;

  courseCount = 0;
  productCount = 0;
  private subscriptions = new Subscription();

  quickTopics: IQuickTopic[] = [
    { title: 'همه دوره‌ها', query: '', icon: 'school-outline' },
    { title: 'روش تدریس الفبا', query: 'فارسی اول', icon: 'book-outline' },
    { title: 'ریاضی اول دبستان', query: 'ریاضی اول', icon: 'calculator-outline' },
    { title: 'کاربرگ هفتگی', query: 'کاربرگ اول', icon: 'documents-outline' },
    { title: 'طرح درس کلاسی', query: 'طرح درس', icon: 'reader-outline' },
    { title: 'مدیریت کلاس اول', query: 'مدیریت کلاس', icon: 'people-outline' },
    { title: 'دست‌ورزی و بازی', query: 'ابزار دست ورزی', icon: 'extension-puzzle-outline' }
  ];

  sortOptions: ISortOption[] = [
    { id: 4, label: 'جدیدترین', icon: 'sparkles-outline' },
    { id: 3, label: 'پربازدیدترین', icon: 'flame-outline' },
    { id: 1, label: 'ارزان‌ترین', icon: 'arrow-down-circle-outline' },
    { id: 2, label: 'گران‌ترین', icon: 'arrow-up-circle-outline' }
  ];

  constructor(
    private activatedRoute: ActivatedRoute,
    private courseService: CourseService,
    private router: Router,
    public modalCtrl: ModalController,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public routerOutlet: IonRouterOutlet,
    public language: SiteLanguageService,
    private menuCtrl: MenuController
  ) { }

  get loggedIn(): boolean {
    return GAccount.IsLoggedIn();
  }

  get cartCount(): number {
    return this.courseCount + this.productCount;
  }

  get currentSortId(): number {
    if (!this.filteredCourses || this.filteredCourses.sortId == null) {
      return 4;
    }
    return +this.filteredCourses.sortId;
  }

  get hasActiveFilters(): boolean {
    if (!this.filteredCourses) {
      return !!(this.queryText && this.queryText.trim().length > 0);
    }
    const hasQuery = !!(this.queryText && this.queryText.trim().length > 0);
    const hasStartPrice = this.filteredCourses.startPrice != null && +this.filteredCourses.startPrice > 0;
    const hasEndPrice = this.filteredCourses.endPrice != null && +this.filteredCourses.endPrice > 0;
    const hasCats = !!(this.filteredCourses.categoryIds && this.filteredCourses.categoryIds.length > 0);
    const hasNonDefaultSort = this.filteredCourses.sortId != null && +this.filteredCourses.sortId !== 4 && +this.filteredCourses.sortId !== 0;

    return hasQuery || hasStartPrice || hasEndPrice || hasCats || hasNonDefaultSort;
  }

  url(path: string): string {
    return this.language.url(path);
  }

  async toggleAppMenu(): Promise<void> {
    await this.menuCtrl.toggle();
  }

  goTop() {
    if (this.content) {
      this.content.scrollToTop(600);
    }
  }

  doRefresh(event: any) {
    setTimeout(() => {
      location.reload();
      event?.target?.complete();
    }, 1500);
  }

  ngOnInit(): void {
    this.subscriptions.add(
      GResponse.getCartCoursesCount().subscribe(count => this.courseCount = count)
    );
    this.subscriptions.add(
      GResponse.getCartProductsCount().subscribe(count => this.productCount = count)
    );

    this.subscriptions.add(
      this.activatedRoute.queryParams.subscribe(params => {
        const page = params.page ? +params.page : 1;
        const take = params.take ? +params.take : 12;
        const title = params.title ? params.title : '';
        const startPrice = params.startPrice ? +params.startPrice : null;
        const endPrice = params.endPrice ? +params.endPrice : null;
        const categoryIds: string = params.categoryIds ? params.categoryIds : null;
        const sortId = params.sortId ? +params.sortId : 4;

        this.queryText = title;

        let filter: ICourseFilterModel;

        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId === 4
        ) {
          filter = new CourseFilterModel(false, page, take, title);
        } else {
          const catIds: number[] = [];
          if (categoryIds != null && categoryIds.length > 0) {
            if (categoryIds.includes(',')) {
              categoryIds.split(',').forEach(cat => catIds.push(+cat));
            } else {
              catIds.push(+categoryIds);
            }
          }
          filter = new CourseFilterModel(true, page, take, title, startPrice, endPrice, catIds, sortId);
        }

        this.filteredCourses = filter;
        this.fetchCourses(filter);
      })
    );
  }

  private fetchCourses(filter: ICourseFilterModel) {
    this.isLoading = true;
    SharedIonic.loading(this.loadingController);

    this.courseService.GetCoursesByFilter(filter).subscribe(
      res => {
        this.isLoading = false;
        SharedIonic.dismissLoading(this.loadingController);

        if (res.status === GResponse.SuccessStatus) {
          this.filteredCourses = res.data;
          const coursesList = res.data?.courses;
          this.notfound = !coursesList || coursesList.length === 0;
        } else if (res.status === GResponse.NotFoundStatus) {
          this.notfound = true;
          SharedIonic.toast(this.toastController, this.language.text('search.noResults'));
        } else {
          this.notfound = true;
        }
      },
      () => {
        this.isLoading = false;
        this.notfound = true;
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطا در برقراری ارتباط با سرور');
      }
    );
  }

  async presentFilter() {
    const modal = await this.modalCtrl.create({
      component: CourseFilterComponent,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { filteredCourses: this.filteredCourses }
    });
    await modal.present();

    const { data } = await modal.onWillDismiss();
    if (data) {
      this.filteredCourses = data;
      this.setQueryParams(1);
    }
  }

  private setQueryParams(pageId: number) {
    if (this.content) {
      this.content.scrollToTop(500);
    }

    const titleVal = this.queryText && this.queryText.trim().length > 0 ? this.queryText.trim() : null;

    this.router.navigate(['Home', 'Search'], {
      queryParams: {
        page: pageId < 1 ? 1 : pageId,
        take: this.filteredCourses?.takeEntity ? this.filteredCourses.takeEntity : 12,
        title: titleVal,
        startPrice: this.filteredCourses?.startPrice ? this.filteredCourses.startPrice : null,
        endPrice: this.filteredCourses?.endPrice ? this.filteredCourses.endPrice : null,
        categoryIds: this.filteredCourses?.categoryIds && this.filteredCourses.categoryIds.length > 0
          ? this.filteredCourses.categoryIds.join(',')
          : null,
        sortId: this.filteredCourses?.sortId != null ? this.filteredCourses.sortId : 4
      }
    });
  }

  search() {
    if (this.filteredCourses) {
      this.filteredCourses.title = this.queryText?.trim() || null;
    }
    this.setQueryParams(1);
  }

  quickSearch(term: string) {
    this.queryText = term;
    if (this.filteredCourses) {
      this.filteredCourses.title = term ? term : null;
    }
    this.setQueryParams(1);
  }

  clearSearch() {
    this.queryText = '';
    if (this.filteredCourses) {
      this.filteredCourses.title = null;
      this.filteredCourses.startPrice = null;
      this.filteredCourses.endPrice = null;
      this.filteredCourses.categoryIds = [];
      this.filteredCourses.sortId = 4;
      this.filteredCourses.isFiltered = false;
    }
    this.setQueryParams(1);
  }

  setSort(sortId: number) {
    if (this.filteredCourses) {
      this.filteredCourses.sortId = sortId;
    }
    this.setQueryParams(1);
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {
    const array: string[] = [];
    const count = +pageCount || 0;
    for (let i = 1; i <= count; i++) {
      array.push(i.toString());
    }
    return array;
  }

  goPreviousPage() {
    if (!this.filteredCourses) { return; }
    if (this.filteredCourses.pageId > 1) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {
    if (!this.filteredCourses) { return; }
    if (this.filteredCourses.pageId < this.filteredCourses.pageCount) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  onSort(event: any) {
    const val = +event.detail.value;
    this.setSort(val);
  }

  isTopicActive(query: string): boolean {
    if (!query) {
      return !this.queryText || this.queryText.trim().length === 0;
    }
    return this.queryText?.trim() === query.trim();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
